// Converte base64 para binário e prepara para extração
const arquivo = $input.item.json.arquivo;

if (!arquivo || !arquivo.base64) {
  return { json: $input.item.json };
}

// Decodifica base64 para Buffer
const buffer = Buffer.from(arquivo.base64, 'base64');

// Determina extensão
let extension = 'bin';
if (arquivo.tipo.includes('pdf')) {
  extension = 'pdf';
} else if (arquivo.tipo.includes('word') || arquivo.tipo.includes('document')) {
  extension = 'docx';
} else if (arquivo.tipo.includes('text')) {
  extension = 'txt';
}

const fileName = `${arquivo.nome}.${extension}`;

return {
  json: {
    ...$input.item.json,
    fileName: fileName,
    mimeType: arquivo.tipo
  },
  binary: {
    data: {
      data: arquivo.base64,
      mimeType: arquivo.tipo,
      fileName: fileName
    }
  }
};

// Combina o texto extraído com o input original
const textoExtraido = $input.item.json.data || $input.item.json.text || '';
const inputOriginal = $('Seletor de Prompt1').item.json.input || '';
const systemMessage = $('Seletor de Prompt1').item.json.system_message || '';
const agente = $('Seletor de Prompt1').item.json.agente || '';
const nomeAgente = $('Seletor de Prompt1').item.json.nome_agente || '';
const nomeArquivo = $('Seletor de Prompt1').item.json.arquivo?.nome || 'documento';
const sessionId = $('Seletor de Prompt1').item.json.sessionId || 'default-session';

// Monta o prompt combinado
let promptFinal = '';

if (inputOriginal && inputOriginal.trim() !== '') {
  promptFinal += `INSTRUÇÕES DO USUÁRIO:\n${inputOriginal}\n\n`;
}

if (textoExtraido && textoExtraido.trim() !== '') {
  promptFinal += `CONTEÚDO DO DOCUMENTO (${nomeArquivo}):\n\n${textoExtraido}`;
}

return {
  json: {
    agente: agente,
    nome_agente: nomeAgente,
    system_message: systemMessage,
    input: promptFinal.trim(),
    texto_extraido: textoExtraido ? true : false,
    sessionId: sessionId
  }
};

// Sem arquivo - passa direto para o agente
return {
  json: {
    agente: $input.item.json.agente,
    nome_agente: $input.item.json.nome_agente,
    system_message: $input.item.json.system_message,
    input: $input.item.json.input,
    sessionId: $input.item.json.sessionId
  }
};

