// ============================================================
// LIMPAR FORMATAÇÃO MARKDOWN
// ============================================================
// Remove caracteres de formatação Markdown da resposta

let texto = $input.item.json.output || $input.item.json.text || '';

// Remove headers markdown (###, ##, #)
texto = texto.replace(/^#{1,6}\s*/gm, '');

// Remove bold (**texto** ou __texto__)
texto = texto.replace(/\*\*([^*]+)\*\*/g, '$1');
texto = texto.replace(/__([^_]+)__/g, '$1');

// Remove itálico (*texto* ou _texto_)
texto = texto.replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, '$1');
texto = texto.replace(/(?<!_)_([^_]+)_(?!_)/g, '$1');

// Remove bullets (* no início da linha)
texto = texto.replace(/^\*\s+/gm, '• ');

// Remove código inline (`texto`)
texto = texto.replace(/`([^`]+)`/g, '$1');

// Remove blocos de código (```...```)
texto = texto.replace(/```[\s\S]*?```/g, '');

// Remove linhas horizontais (---, ___, ***)
texto = texto.replace(/^[-_*]{3,}$/gm, '');

// Remove múltiplas quebras de linha consecutivas
texto = texto.replace(/\n{3,}/g, '\n\n');

// Trim
texto = texto.trim();

return {
  json: {
    ...$input.item.json,
    output: texto,
    text: texto
  }
};

// Extração robusta de texto para PDF, DOCX e TXT
const binaryData = $input.item.binary?.data;

if (!binaryData) {
  return { 
    json: { 
      ...$input.item.json,
      data: '',
      error: 'Nenhum arquivo binário encontrado' 
    } 
  };
}

const buffer = Buffer.from(binaryData.data, 'base64');
const mimeType = (binaryData.mimeType || '').toLowerCase();
const fileName = binaryData.fileName || 'documento';

let textoExtraido = '';
let erro = null;

// ========== PDF ==========
if (mimeType.includes('pdf')) {
  try {
    const pdfParse = require('pdf-parse');
    const pdfData = await pdfParse(buffer);
    textoExtraido = pdfData.text;
  } catch (err) {
    erro = 'Erro ao extrair PDF: ' + err.message;
  }
}

// ========== DOCX ==========
else if (mimeType.includes('word') || mimeType.includes('document') || mimeType.includes('officedocument') || mimeType.includes('msword')) {
  try {
    const mammoth = require('mammoth');
    const result = await mammoth.extractRawText({ buffer: buffer });
    textoExtraido = result.value;
  } catch (err) {
    erro = 'Erro ao extrair DOCX: ' + err.message;
  }
}

// ========== TXT ==========
else if (mimeType.includes('text')) {
  textoExtraido = buffer.toString('utf-8');
}

// ========== Outros ==========
else {
  erro = 'Tipo de arquivo não suportado: ' + mimeType;
}

// Limpa o texto extraído
if (textoExtraido) {
  textoExtraido = textoExtraido
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

return {
  json: {
    ...$input.item.json,
    data: textoExtraido,
    text: textoExtraido,
    fileName: fileName,
    mimeType: mimeType,
    extractionError: erro,
    charCount: textoExtraido ? textoExtraido.length : 0
  }
};
